Object.assign(labels,{created_at:"Thời điểm chạy",model:"Mô hình",dataset:"Nguồn",prediction:"SOH ước tính (%)",loss_pct:"Mức chai ước tính (%)",temp_max_c:"Nhiệt độ cao nhất (°C)",outcome:"Đối chiếu tín hiệu"});

