  if(!put(header('Phân tích sức khỏe pin','Bắt đầu bằng file của bạn hoặc dữ liệu mẫu đã có.')+workflowSteps(1)+panel('Dữ liệu pin cần phân tích','CSV/CSV.GZ tối đa 512 MiB; JSON dạng bảng tối đa 20 MiB. File nhiều pin/chu kỳ sẽ được lọc ở bước tiếp theo.',`<div class="field"><label for="check-file">Chọn file của bạn</label><input id="check-file" type="file" accept=".csv,.csv.gz,.gz,.json"></div><div id="check-detected" aria-live="polite"></div><div class="actions"><button class="button primary" id="check-open">Mở bộ tiếp nhận dữ liệu</button><button class="button" id="check-example">Thử dữ liệu mẫu BAIC</button></div>`)+`<details><summary>Chọn trực tiếp nguồn đã được hỗ trợ</summary><div class="actions"><a class="button" href="#forecast">Pin SDU · NMC 2,4 Ah</a><a class="button" href="#bms">Xe BAIC EU500 · 145 Ah</a><a class="button" href="#capacity">Có dung lượng đo đầy đủ</a></div><p>Đổi tên cột không chứng minh mô hình phù hợp với pin khác. Bộ tiếp nhận cho phép khai báo cấu hình trước khi chọn cách phân tích.</p></details>`,token))return;
