  const open=()=>{const file=$('#check-file').files[0];if(file){const max=/\.json$/i.test(file.name)?20:512;if(file.size>max*1024*1024){toast('File vượt '+max+' MiB.');return;}if(!/\.(csv|gz|json)$/i.test(file.name)){toast('Chỉ nhận CSV, CSV.GZ hoặc JSON.');return;}}pendingUpload=file?{target:'mapping',file}:null;location.hash='mapping';};$('#check-open').onclick=open;
  $('#check-file').onchange=()=>{const f=$('#check-file').files[0];$('#check-detected').innerHTML=f?`<p>${esc(f.name)} · ${fmt(f.size/1024/1024,2)} MiB. Bấm mở để xem cột và chọn pin/chu kỳ.</p>`:'';};
