async function profile(token){put(header("Thông tin đề tài","Phân tích và dự đoán tình trạng sức khỏe pin xe điện bằng các mô hình học máy")+`<div class="grid-equal">${panel("Tác giả","",'<div class="profile"><img src="/assets/logo.png" alt="Logo Vincent D"><div><h2>Nguyễn Văn Duy</h2><p>MSSV 2311553949</p><span class="muted">Khoa Học Dữ Liệu · Lớp 23DTH2A</span></div></div><p>Trường Đại học Nguyễn Tất Thành</p><p>GVHD: ThS. Vương Xuân Chí</p>')}${panel("Chỉ số sức khỏe pin","",'<p><strong>SOH:</strong> sức khỏe dung lượng = dung lượng tham chiếu / dung lượng danh định × 100%.</p><p><strong>Mức chai:</strong> 100 − SOH, khi SOH không vượt 100%. <strong>SOC:</strong> mức điện đang còn, khác SOH.</p><p class="sub">SDU: 2,4 Ah; dữ liệu tế bào trong phòng thí nghiệm. BMS: bộ pin 145 Ah, nhãn dung lượng vận hành suy ra từ dòng điện/SOC.</p><p>Dự báo thử nghiệm thời điểm SOH xuống ngưỡng dung lượng; không dự báo ngày xảy ra sự cố và không chứng nhận an toàn.</p>')}</div>`+panel("Nguồn SDU","Cell Lishen LR1865SZ · NMC(532)/graphite",'<p class="source">Shuquan Wang, Feng Gao và Hao Tian, Đại học Sơn Đông (Trung Quốc). Công bố 12/02/2025, CC BY 4.0. <a href="https://doi.org/10.5281/zenodo.14859405" target="_blank" rel="noopener">Dữ liệu Zenodo</a> · <a href="https://doi.org/10.1016/j.xcrp.2025.102657" target="_blank" rel="noopener">Bài báo liên quan</a>.</p>')+panel("Nguồn BMS trên xe","20 xe BAIC EU500 · bộ pin 145 Ah",'<p class="source">Deng và cộng sự · Applied Energy (2023) · <a href="https://doi.org/10.1016/j.apenergy.2023.120954" target="_blank" rel="noopener">Bài báo nguồn</a> · <a href="https://github.com/BatICM/battery-charging-data-of-on-road-electric-vehicles" target="_blank" rel="noopener">Dữ liệu công bố</a>.</p><p>SOH suy ra từ dòng điện/SOC sau cửa sổ đầu sạc, tổng hợp theo xe–tháng; không phải phép đo dung lượng độc lập.</p>')+panel("Nguồn điện áp có nhãn lỗi","99 xe · 47.698 mẫu cell–snapshot · dữ liệu xử lý",'<p class="source">Li và cộng sự · <a href="https://zenodo.org/records/18505707" target="_blank" rel="noopener">Zenodo 18505707 v1</a> · CC BY 4.0.</p><p>Phân loại nhị phân bằng Random Forest; kiểm thử 5 vòng theo xe. Đây là dữ liệu riêng, không gắn nhãn lỗi sang pin SDU hoặc xe BAIC.</p>')+panel("NASA · kiểm chứng ngoài nguồn","4 cell · 636 chu kỳ xả",'<p>Dữ liệu NASA dùng để kiểm tra mô hình SDU trên pin ngoài nguồn và thí nghiệm giữ riêng cell. Kết quả chuyển miền còn kém; không dùng mô hình này cho mọi pin.</p><a class="button" href="#research">Xem thực nghiệm NASA trong Phân tích chuyên sâu</a>')+panel("Phương pháp và phạm vi","",'<p>Ridge, Random Forest, LightGBM, GRU, CatBoost và XGBoost là thuật toán đã công bố. Ridge–RF là phương án kết hợp thuật toán có sẵn, không khẳng định thuật toán mới.</p><p class="sub">Chọn cấu hình CatBoost/XGBoost bằng validation giữ riêng pin bên trong tập học. Kết quả kiểm thử được giữ tách khỏi mô hình bàn giao học lại toàn bộ dữ liệu.</p><p class="sub">Lịch sử dự đoán chỉ nằm trong tab trình duyệt. Không có cơ sở dữ liệu lịch sử chung giữa người dùng.</p>'),token);}
