function toast(text){const node=$("#toast");node.textContent=text;node.style.display="block";clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.style.display="none",4500);}
$("#theme").onclick=()=>{const dark=document.documentElement.dataset.theme!=="dark";document.documentElement.dataset.theme=dark?"dark":"light";try{localStorage.setItem("vincent-theme",dark?"dark":"light");}catch(e){}$("#theme").setAttribute("aria-pressed",String(dark));};
$("#menu-toggle").onclick=()=>{const sidebar=document.querySelector(".sidebar"),open=sidebar.classList.toggle("menu-open");$("#menu-toggle").setAttribute("aria-expanded",String(open));};
window.addEventListener("hashchange",route);route();
